<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{api}from'../services/api';const username=ref(''),password=ref(''),error=ref(''),r=useRouter();async function login(){try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:username.value,password:password.value})});r.push('/dashboard')}catch(e:any){error.value=e.message}}</script>
<template><div class="login"><div class="box"><div class="logo"><v-icon size="50">mdi-account-group</v-icon></div><h1>ITCA-Mangement</h1><p>Quản lý ngày làm việc</p><v-text-field v-model="username" label="Tên đăng nhập" prepend-inner-icon="mdi-account"/><v-text-field v-model="password" label="Mật khẩu" type="password" prepend-inner-icon="mdi-lock" @keyup.enter="login"/><v-alert v-if="error" type="error" density="compact">{{error}}</v-alert><v-btn block size="large" color="#8b0d24" @click="login">Đăng nhập</v-btn></div></div></template>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:linear-gradient(145deg,#74091d,#a5102e 45%,#fff3f5 45%)}.box{width:min(430px,92vw);background:white;padding:34px;border-radius:24px;box-shadow:0 25px 60px #4b001533;text-align:center}.logo{color:#8b0d24}.box h1{color:#8b0d24;margin:8px 0 0}.box p{color:#697386;margin-bottom:25px}</style>
